static void fill(GGSurface s,int x,int y,int w,int h,uint32_t c){if(x<0){w+=x;x=0;}if(y<0){h+=y;y=0;}if(x+w>(int)s.width)w=s.width-x;if(y+h>(int)s.height)h=s.height-y;if(w<=0||h<=0)return;for(int yy=y;yy<y+h;yy++)for(int xx=x;xx<x+w;xx++)gg_platform_put_pixel(xx,yy,c);}
