static void txt(GGSurface s,int x,int y,const char*t,int z,uint32_t c){for(;*t;t++,x+=6*z)glyph(s,x,y,*t,z,c);}
void gg_draw_retrohub_frame(GGSurface s,int sel){static const uint32_t a[5]={0xffd9d9d9,0xffaa6688,0xff3535d0,0xffe07838,0xff27a7d2};static const char*n[5]={"NES","SNES","N64","GENESIS","PLAYSTATION"};fill(s,0,0,s.width,s.height,0xff090d18);fill(s,0,0,s.width,18,0xff2d7df6);txt(s,100,70,"GOLDENGAMES RETROHUB PRO",5,0xffffffff);txt(s,102,125,"NATIVE TITLE - BUILD 002",2,0xff9fb4d8);fill(s,0,205,s.width,8,0xff2d7df6);for(int i=0;i<5;i++){int d=i-sel;int w=d==0?330:230,h=d==0?450:330,x=960+d*300-w/2,y=d==0?300:360;fill(s,x-6,y-6,w+12,h+12,a[i]);fill(s,x,y,w,h,0xff171d2a);txt(s,x+24,y+h/2,n[i],2,0xffffffff);}txt(s,790,805,n[sel],4,0xffffffff);fill(s,0,955,s.width,125,0xff05070c);txt(s,120,990,"LEFT RIGHT  X SELECT",2,0xffffffff);txt(s,1190,990,"GOLDENGAMES V0.2",2,0xff9fb4d8);}
